INSERT INTO daily_sparks (active_date, age_tier, category, title, prompt_text, options, fact_explanation, xp_reward)
VALUES
('2026-09-01', 1, 'MYTH_VS_REALITY', 'Mito: Los Videojuegos son solo para pasar el rato', '¿Cuál crees que es el mayor superpoder que desarrolla una persona que juega y diseña videojuegos?', '[{"id": "A", "text": "Coordinación motriz fina, reflejos visuales rápidos y comprensión de mecánicas físicas", "feedback": "¡Destreza Motriz y Lógica! Ves en los juegos un campo de entrenamiento de precisión espacial.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Empatía con personajes, creación de historias inmersivas y diseño de bandas sonoras", "feedback": "¡Narrativa y Resonancia Emocional! Reconoces que los videojuegos son el arte interactivo del siglo XXI.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Estrategia para resolver acertijos complejos, calcular probabilidades y optimizar recursos", "feedback": "¡Pensamiento Estratégico y Analítico! Destacas por planificar jugadas con frialdad y lógica.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'Pilotos de aviación y cirujanos laparoscópicos en todo el mundo se entrenan con simuladores basados en tecnología y físicas de videojuegos.', 30),
('2026-09-02', 1, 'MULTI_CHOICE_RIASEC', 'Misión en la Reserva Ecológica', 'Tu grupo escolar es voluntario para proteger una laguna amenazada por sequía. ¿Dónde aportas más?', '[{"id": "A", "text": "Monitorear la calidad del agua con sensores químicos y construir filtros naturales con piedras", "feedback": "¡Vocación Realista e Investigativa! Te fascina la acción directa en el terreno y medir variables con datos.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Pintar un mural ecológico y guiar recorridos didácticos para los niños de la comunidad", "feedback": "¡Vocación Artística y Social! Tu fortaleza es conectar corazones y movilizar a la comunidad a través del arte.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Organizar las donaciones de empresas locales, coordinar los turnos y rendir cuentas al guardaparques", "feedback": "¡Vocación Emprendedora y Convencional! Aseguras que las iniciativas ciudadanas tengan orden, fondos y continuidad.", "traitWeights": {"E": 2, "C": 1}}]'::jsonb, 'La conservación ambiental exitosa requiere la integración simultánea de ciencia ambiental, educación artística comunitaria y gestión eficiente de recursos.', 30),
('2026-09-03', 1, 'AI_FUTURE_TRENDS', 'El Robot Asistente en la Escuela', 'Tu colegio incorpora un robot con Inteligencia Artificial para apoyar a los alumnos. ¿Cómo debería colaborar contigo?', '[{"id": "A", "text": "Ayudándote a simular experimentos científicos complejos de física y química en 3D", "feedback": "¡Curiosidad Científica Aumentada! Utilizas la tecnología como un microscopio para ver lo invisible.", "traitWeights": {"I": 2, "R": 1}}, {"id": "B", "text": "Generando efectos de sonido, ilustraciones y ayudándote a pulir tus relatos y animaciones", "feedback": "¡Co-creación Creativa! Ves la IA como un pincel mágico que amplifica tus ideas originales.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Analizando tus patrones de estudio, programando recordatorios y organizando tus resúmenes", "feedback": "¡Eficiencia y Metacognición! Sabes que dominar tu propio tiempo es la clave del alto rendimiento.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'Estudios educativos demuestran que los estudiantes que usan herramientas generativas para estructurar ideas aprenden un 40% más rápido cuando mantienen el juicio crítico.', 30),
('2026-09-04', 1, 'INDUSTRY_CULTURE', 'El Rescate de un Espacio Juvenil', 'El centro cultural juvenil de tu barrio necesita un cambio urgente antes de reabrir. ¿Dónde aportas más energía?', '[{"id": "A", "text": "Restaurar muebles, instalar rampas accesibles y cablear el sistema de iluminación y sonido", "feedback": "¡Espíritu Constructor y Resolutivo! Tu valor radica en hacer que las cosas funcionen en el mundo real.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Diseñar la gráfica de los muros, elegir la paleta de colores y organizar talleres de teatro", "feedback": "¡Identidad Visual y Dinamismo Social! Creas atmósferas donde las personas se sienten inspiradas.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Crear una campaña en redes, hablar con patrocinadores locales y coordinar el cronograma", "feedback": "¡Gestión y Liderazgo Comunitario! Tienes la chispa para movilizar recursos y transformar ideas en realidad.", "traitWeights": {"E": 2, "C": 1}}]'::jsonb, 'Organizaciones juveniles globales demuestran que los proyectos comunitarios exitosos requieren tanto constructores prácticos como artistas de la comunicación y gestores de alianzas.', 30),
('2026-09-05', 1, 'PRACTICAL_MICRO_ACTION', 'El Misterio de la Bicicleta de Ruta', 'Vas a acondicionar tu bicicleta para una travesía larga el fin de semana. ¿En qué detalle te fijas primero?', '[{"id": "A", "text": "Calibrar frenos, engrasar la cadena, verificar la presión de aire y empacar herramientas de repuesto", "feedback": "¡Atención al Detalle Mecánico! Previenes problemas dominando la física y el mantenimiento del equipo.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Personalizar el diseño con luces LED de colores, stickers reflectantes y armar la lista de música", "feedback": "¡Estilo y Expresión Personal! Haces que cada actividad cotidiana sea una experiencia visualmente única.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Mapear la ruta en GPS, calcular paradas con sombra e hidratación y coordinar horarios del grupo", "feedback": "¡Logística y Seguridad Colectiva! Tu mente anticipa variables para que toda la expedición sea un éxito.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'La bicicleta es uno de los inventos mecánicos más eficientes de la historia humana: convierte el 90% de la energía de los músculos en movimiento hacia adelante.', 30),
('2026-09-06', 1, 'ETHICAL_DILEMMA', 'El Experimento del Torneo de Robótica', 'Durante la final del torneo de robótica escolar, descubres un error en la pista que beneficia a tu robot. ¿Qué haces?', '[{"id": "A", "text": "Reprogramar el sensor de tu robot en 5 minutos para demostrar que puede ganar sin ninguna ventaja", "feedback": "¡Orgullo Técnico y Desafío Ingenieril! Te apasiona ganar por mérito propio y superación técnica.", "traitWeights": {"I": 2, "R": 1}}, {"id": "B", "text": "Avisar de inmediato a los organizadores y a los demás equipos para que la competencia sea justa", "feedback": "¡Honestidad y Espíritu Comunitario! Valoras el compañerismo y la confianza por encima de cualquier trofeo.", "traitWeights": {"S": 2, "A": 1}}, {"id": "C", "text": "Pedir una pausa a los jueces, presentar evidencia fotográfica del error y solicitar una prueba oficial", "feedback": "¡Criterio Normativo y Liderazgo Institucional! Buscas que las reglas sean transparentes y respetadas por todos.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'En torneos internacionales como FIRST Robotics, el premio más prestigioso no es al robot más veloz, sino al equipo que demuestra ''Gracious Professionalism'' (ética, respeto y cooperación).', 30),
('2026-09-07', 1, 'DILEMMA_WORK_VALUES', 'El Gran Proyecto de la Feria Escolar', 'Tu colegio organiza la feria anual de proyectos de innovación. Si tu equipo pudiera elegir su forma de trabajar, ¿cuál preferirías?', '[{"id": "A", "text": "Construir maquetas funcionales, ensamblar piezas y probar circuitos en el taller", "feedback": "¡Perfil Práctico e Investigativo! Disfrutas crear con tus manos y entender la física de las cosas.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Diseñar los pósteres visuales, editar videos dinámicos y coordinar dinámicas para los visitantes", "feedback": "¡Perfil Creativo y Social! Tu magia está en inspirar a la gente y comunicar emociones visualmente.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Organizar el cronograma, administrar el presupuesto de materiales y presentar a los jueces", "feedback": "¡Perfil Emprendedor y Organizado! Tienes visión de liderazgo, orden y capacidad de persuasión.", "traitWeights": {"E": 2, "C": 1}}]'::jsonb, 'Los proyectos escolares destacados funcionan igual que los equipos de innovación moderna: combinan creadores técnicos, diseñadores de experiencias y coordinadores organizados.', 30),
('2026-09-08', 1, 'MYTH_VS_REALITY', 'Mito: La Ciencia es solo para genios encerrados en laboratorios', '¿Qué habilidad hace que un científico joven realmente cambie el mundo hoy?', '[{"id": "A", "text": "Construir prototipos de bajo costo con impresoras 3D para llevar ciencia a lugares remotos", "feedback": "¡Ingenio Práctico y Social! Crees en la tecnología accesible que resuelve problemas reales.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Hacer divulgación divertida en redes sociales con ilustraciones y videos que todos entiendan", "feedback": "¡Comunicación y Arte Científico! Tu talento es traducir datos difíciles en historias fascinantes.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Liderar movimientos juveniles y conseguir apoyo de empresas para financiar expediciones", "feedback": "¡Liderazgo y Gestión de Impacto! Sabes que las grandes ideas necesitan recursos para despegar.", "traitWeights": {"E": 2, "C": 1}}]'::jsonb, 'Grandes inventos modernos, como detectores de microplásticos y sensores solares accesibles, han sido creados por adolescentes menores de 16 años combinando curiosidad y diseño.', 30),
('2026-09-09', 1, 'MULTI_CHOICE_RIASEC', 'Construyendo la Ciudad del Futuro', 'En una simulación de urbanismo sustentable en el colegio, te asignan diseñar un nuevo barrio. ¿Cuál es tu prioridad?', '[{"id": "A", "text": "Diseñar ciclovías inteligentes, semáforos solares y estaciones mecánicas de reciclaje", "feedback": "¡Ingeniería Física y Sustentable! Piensas en la infraestructura tangible que mejora la vida diaria.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Crear parques con esculturas interactivas, espacios culturales y centros de encuentro juvenil", "feedback": "¡Humanismo y Diseño Sensorial! Sabes que una ciudad necesita alma, belleza y vida comunitaria.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Optimizar el mapa de transporte público con datos, calcular presupuestos y atraer comercios locales", "feedback": "¡Planificación y Economía Urbana! Tu fortaleza es la viabilidad financiera y la logística eficiente.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'Las ciudades inteligentes más premiadas del mundo (como Tokio o Copenhague) son diseñadas por equipos donde arquitectos, ingenieros civiles y sociólogos trabajan en conjunto.', 30),
('2026-09-10', 1, 'AI_FUTURE_TRENDS', 'La Creación de Música con Algoritmos', 'Un software de IA compone una melodía genial en segundos. ¿Cuál es el rol insustituible del creador humano?', '[{"id": "A", "text": "Programar los sintetizadores analógicos, conectar los cables de audio y afinar los instrumentos acústicos", "feedback": "¡Apreciación del Hardware y Acústica! Valoras la física del sonido y el tacto del instrumento real.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Poner la emoción, la letra poética y la vulnerabilidad de una experiencia que conmueva a las personas", "feedback": "¡Sensibilidad y Alma Artística! Sabes que la música sin vivencias reales es solo matemática vacía.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Detectar qué ritmo conectará con el público, armar la estrategia de lanzamiento y proteger los derechos", "feedback": "¡Visión de Industria y Gestión! Entiendes cómo conectar una gran obra con su audiencia adecuada.", "traitWeights": {"E": 2, "C": 1}}]'::jsonb, 'Grandes productores modernos combinan herramientas generativas para generar texturas, pero la armonía final y la emoción vocal siempre son definidas por el oído humano.', 30),
('2026-09-11', 1, 'INDUSTRY_CULTURE', 'El Misterio del Video Viral', 'Un video educativo creado por estudiantes de tu edad alcanza 1 millón de vistas. ¿Qué componente fue el más decisivo?', '[{"id": "A", "text": "La rigurosidad técnica de los datos y el experimento visual impecable que mostraron", "feedback": "¡Credibilidad y Curiosidad Científica! Sabes que la verdad empírica bien mostrada es fascinante.", "traitWeights": {"I": 2, "R": 1}}, {"id": "B", "text": "El humor, la edición artística de cortes rápidos y la empatía con la que le hablaron a su generación", "feedback": "¡Conexión Humana y Creatividad Audiovisual! Sabes que sin emoción y relato visual nadie se queda a mirar.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "El análisis de las tendencias del algoritmo, el título gancho y el horario exacto de publicación", "feedback": "¡Pensamiento Estratégico y Datos de Audiencia! Entiendes la ciencia de la distribución y la visibilidad digital.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'El éxito en plataformas digitales modernas es un triángulo perfecto: contenido de valor objetivo, narrativa visual empática y optimización analítica de distribución.', 30),
('2026-09-12', 1, 'PRACTICAL_MICRO_ACTION', 'El Secreto del Desayuno Energético', 'Tienes una mañana exigente de exámenes y deporte en el colegio. ¿Cómo preparas tu desayuno?', '[{"id": "A", "text": "Cocinando algo nutritivo desde cero: huevos, frutas frescas y manejando sartenes con destreza", "feedback": "¡Acción Práctica y Sensorial! Disfrutas la transformación tangible de alimentos frescos.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Sirviendo una presentación colorida y estética mientras escuchas un podcast inspirador", "feedback": "¡Bienestar Integral y Creativo! Creas momentos de armonía que te recargan de energía positiva.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Revisando el aporte de proteínas y carbohidratos, y dejando todo medido y lavado en 10 minutos", "feedback": "¡Optimización y Criterio Nutricional! Tratas tus hábitos con disciplina y rigor para rendir al máximo.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'La neurociencia del aprendizaje demuestra que un desayuno equilibrado con glucosa de absorción lenta mejora en un 30% la memoria de trabajo y la atención sostenida.', 30),
('2026-09-13', 1, 'ETHICAL_DILEMMA', 'La App de Calificaciones y la Privacidad', 'El colegio planea instalar una app que monitorea cada segundo de pantalla de los alumnos para medir su atención. ¿Cuál es tu postura?', '[{"id": "A", "text": "Auditar técnicamente el código de la app para ver qué datos envía y proponer alternativas de software abierto", "feedback": "¡Pensamiento Crítico y Seguridad Digital! Buscas entender la tecnología antes de aceptarla a ciegas.", "traitWeights": {"I": 2, "R": 1}}, {"id": "B", "text": "Liderar un debate estudiantil pacífico expresando que la confianza y el bienestar emocional son más importantes", "feedback": "¡Defensa de los Derechos y Empatía! Tu voz defiende el respeto a la dignidad y la tranquilidad de las personas.", "traitWeights": {"S": 2, "A": 1}}, {"id": "C", "text": "Proponer un protocolo formal con delegados de padres y profesores para fijar límites estrictos de uso", "feedback": "¡Gobernanza y Mediación Equilibrada! Sabes conciliar la seguridad con la privacidad mediante acuerdos claros.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'La bioética digital contemporánea establece que el monitoreo invasivo de menores en entornos educativos genera estrés crónico y desincentiva la autoeficacia.', 30),
('2026-09-14', 1, 'DILEMMA_WORK_VALUES', 'Tu Espacio Creativo Ideal', 'Imagina que puedes diseñar el rincón perfecto en tu casa para tus proyectos favoritos. ¿Cómo lo equiparías?', '[{"id": "A", "text": "Una mesa con herramientas, kits de robótica, sensores y piezas para desarmar y experimentar", "feedback": "¡Mente Técnica y Curiosa! Te apasiona la experimentación directa y crear tecnología tangible.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Un estudio con tableta gráfica, instrumentos musicales, buena iluminación y espacio para dibujar", "feedback": "¡Sensibilidad Artística y Expresiva! Tu energía fluye a través del arte, el sonido y la imaginación.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Un escritorio minimalista con doble pantalla, pizarras de planificación y organizadores de tareas", "feedback": "¡Visión Estratégica y Enfocada! Valoras la claridad mental, el orden y la eficiencia de tus objetivos.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'El entorno físico influye directamente en los tipos de pensamiento: el desorden creativo estimula la divergencia, mientras que el orden sistemático potencia la concentración analítica.', 30),
('2026-09-15', 1, 'MYTH_VS_REALITY', 'Mito: Los Videojuegos son solo para pasar el rato', '¿Cuál crees que es el mayor superpoder que desarrolla una persona que juega y diseña videojuegos?', '[{"id": "A", "text": "Coordinación motriz fina, reflejos visuales rápidos y comprensión de mecánicas físicas", "feedback": "¡Destreza Motriz y Lógica! Ves en los juegos un campo de entrenamiento de precisión espacial.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Empatía con personajes, creación de historias inmersivas y diseño de bandas sonoras", "feedback": "¡Narrativa y Resonancia Emocional! Reconoces que los videojuegos son el arte interactivo del siglo XXI.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Estrategia para resolver acertijos complejos, calcular probabilidades y optimizar recursos", "feedback": "¡Pensamiento Estratégico y Analítico! Destacas por planificar jugadas con frialdad y lógica.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'Pilotos de aviación y cirujanos laparoscópicos en todo el mundo se entrenan con simuladores basados en tecnología y físicas de videojuegos.', 30),
('2026-09-16', 1, 'MULTI_CHOICE_RIASEC', 'Misión en la Reserva Ecológica', 'Tu grupo escolar es voluntario para proteger una laguna amenazada por sequía. ¿Dónde aportas más?', '[{"id": "A", "text": "Monitorear la calidad del agua con sensores químicos y construir filtros naturales con piedras", "feedback": "¡Vocación Realista e Investigativa! Te fascina la acción directa en el terreno y medir variables con datos.", "traitWeights": {"R": 2, "I": 1}}, {"id": "B", "text": "Pintar un mural ecológico y guiar recorridos didácticos para los niños de la comunidad", "feedback": "¡Vocación Artística y Social! Tu fortaleza es conectar corazones y movilizar a la comunidad a través del arte.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Organizar las donaciones de empresas locales, coordinar los turnos y rendir cuentas al guardaparques", "feedback": "¡Vocación Emprendedora y Convencional! Aseguras que las iniciativas ciudadanas tengan orden, fondos y continuidad.", "traitWeights": {"E": 2, "C": 1}}]'::jsonb, 'La conservación ambiental exitosa requiere la integración simultánea de ciencia ambiental, educación artística comunitaria y gestión eficiente de recursos.', 30),
('2026-09-17', 1, 'AI_FUTURE_TRENDS', 'El Robot Asistente en la Escuela', 'Tu colegio incorpora un robot con Inteligencia Artificial para apoyar a los alumnos. ¿Cómo debería colaborar contigo?', '[{"id": "A", "text": "Ayudándote a simular experimentos científicos complejos de física y química en 3D", "feedback": "¡Curiosidad Científica Aumentada! Utilizas la tecnología como un microscopio para ver lo invisible.", "traitWeights": {"I": 2, "R": 1}}, {"id": "B", "text": "Generando efectos de sonido, ilustraciones y ayudándote a pulir tus relatos y animaciones", "feedback": "¡Co-creación Creativa! Ves la IA como un pincel mágico que amplifica tus ideas originales.", "traitWeights": {"A": 2, "S": 1}}, {"id": "C", "text": "Analizando tus patrones de estudio, programando recordatorios y organizando tus resúmenes", "feedback": "¡Eficiencia y Metacognición! Sabes que dominar tu propio tiempo es la clave del alto rendimiento.", "traitWeights": {"C": 2, "E": 1}}]'::jsonb, 'Estudios educativos demuestran que los estudiantes que usan herramientas generativas para estructurar ideas aprenden un 40% más rápido cuando mantienen el juicio crítico.', 30),
